cargo test -p jackioh-cards c089_paul_allens_ghost
cargo test -p jackioh-cards c033_joro
cargo test -p jackioh-cards -- c070_book_of_plague c076_plague_bringer c054_rewind
cargo test -p jackioh-engine --features testkit --test 'rules*' r450
cargo test -p jackioh-engine --features testkit --test 'rules*'
